// ==============================================================================
// global.d.ts - 全局类型定义
// ==============================================================================
//
// 本文件扩展全局类型定义，避免使用 (window as any) 等类型断言。
//
// ==============================================================================

/**
 * 扩展 Window 接口，添加应用特定的全局属性
 */
declare global {
  interface Window {
    /**
     * 应用配置
     */
    __APP_CONFIG__?: {
      version: string;
      env: string;
      apiBaseURL: string;
    };

    /**
     * 调试工具（仅开发环境）
     */
    __DEV_TOOLS__?: {
      enableLogger: () => void;
      disableLogger: () => void;
      setLogLevel: (level: number) => void;
    };
  }
}

/**
 * 导出全局类型，确保文件作为模块处理
 */
export {};
